import shutil
import re
from datetime import date, datetime
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title] if ws.title in vals.sheetnames else vals.active

MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12
}

def parse_side(raw):
    if raw is None:
        return None

    s = str(raw).strip()
    if not s:
        return None

    # Remove ordinal suffixes like 2nd, 5th, etc.
    s = re.sub(r"(\d{1,2})(st|nd|rd|th)\b", r"\1", s, flags=re.IGNORECASE)

    # Try common explicit date formats.
    formats = [
        "%m/%d", "%m-%d", "%m.%d",
        "%d/%m", "%d-%m", "%d.%m",
        "%m/%d/%Y", "%m-%d-%Y",
        "%Y/%m/%d", "%Y-%m-%d"
    ]
    for fmt in formats:
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            pass

    # Month name + day, e.g. "June 2"
    m = re.match(r"^([A-Za-z]+)\s+(\d{1,2})$", s)
    if m:
        key = m.group(1).lower()[:3]
        if key in MONTHS:
            try:
                return date(2000, MONTHS[key], int(m.group(2)))
            except ValueError:
                pass

    # Day + month name, e.g. "2 June"
    m = re.match(r"^(\d{1,2})\s+([A-Za-z]+)$", s)
    if m:
        key = m.group(2).lower()[:3]
        if key in MONTHS:
            try:
                return date(2000, MONTHS[key], int(m.group(1)))
            except ValueError:
                pass

    # Bare day number: interpret as a day in June, matching the example.
    m = re.search(r"\d{1,2}", s)
    if m:
        day = int(m.group())
        if 1 <= day <= 31:
            return date(2000, 6, day)

    return None

def inclusive_days(text):
    if text is None:
        return None

    s = str(text).strip()
    if not s:
        return None

    # Split on "to"
    parts = re.split(r"\s+to\s+|\bto\b", s, maxsplit=1, flags=re.IGNORECASE)
    if len(parts) == 2:
        d1 = parse_side(parts[0])
        d2 = parse_side(parts[1])
        if d1 is not None and d2 is not None:
            return abs((d2 - d1).days) + 1

    # Fallback: use the first two numbers found.
    nums = re.findall(r"\d+", s)
    if len(nums) >= 2:
        return abs(int(nums[1]) - int(nums[0])) + 1

    return None

a_val = vws["A2"].value
if a_val is None and "Sheet1" in vals.sheetnames:
    a_val = vals["Sheet1"]["A2"].value

result = inclusive_days(a_val)
ws["B2"] = int(result) if result is not None else None

print("active sheet:", ws.title)
print("A2:", repr(a_val))
print("B2:", ws["B2"].value)

wb.save(OUT)
